usage() {
  cat <<USAGE
Usage: bootstrap.sh [--rotate-token] [--reset <KEY>] [--help]

  --reset <KEY>   Forget a persisted .env value so the next run re-asks for it.
                  A wrong credential is otherwise permanent: the value is stored
                  before it can be validated, and the environment-first ladder
                  means a re-run never re-prompts.
  --rotate-token  Mint a second read token, store it, then revoke the first (new before old).
                  Use after an App key rotation or a suspected token leak. Re-running WITHOUT this flag
                  after an App key rotation re-copies the two values (stage 2) on a hash difference.
  --help          This text.

Environment:
  SOLEUR_BOOTSTRAP_LEDGER=<path>     Run ledger (default: beside this script).
  SOLEUR_OP_LIB=<abs-path>           Override the library path baked at generation.

Skip variables — one per class-1/class-3 prompt in THIS script, derived from
its source so the list cannot drift (naming convention: SOLEUR_BOOTSTRAP_<WHAT>
for a value, SOLEUR_BOOTSTRAP_SKIP_<WHAT>_BARRIER for a barrier). The
destructive-write acknowledgement has NONE, by rule:
$(grep -oE '^[[:space:]]*soleur_op_(barrier|value) SOLEUR_BOOTSTRAP_[A-Z0-9_]+' "${BASH_SOURCE[0]}" | awk '{print "  " $2}' | sort -u | grep . || echo '  (none: this script has no class-1 or class-3 prompt)')
USAGE
}

# --- argument validation -----------------------------------------------------
# Deliberately ABOVE the EXIT trap installed below: a usage error must print no
# "Stopped during stage" banner, and `--reset` is not a stage.
RESET_KEY=""
while [[ $# -gt 0 ]]; do
  case "$1" in
    --reset) RESET_KEY="${2:-}"; [[ -n "$RESET_KEY" ]] || { echo "Error: --reset needs a KEY" >&2; usage >&2; exit 1; }; shift 2 ;;
    --rotate-token) ROTATE_TOKEN=1; shift ;;
    --help|-h) usage; exit 0 ;;
    *) echo "Unknown argument: $1" >&2; usage >&2; exit 1 ;;
  esac
done

# --- the credentials file must be ignored by git ------------------------------
# This script lives in a TRACKED directory (SKILL.md §Where), and its .env holds
# live credentials. A .gitignore that does not cover it turns the founder's next
# `git add .` into a pushed token (review P1-1). Checked BEFORE the first write —
# `--reset` writes too — on the .env AND on the `.tmp.XXXXXX` sibling the upsert
# creates beside it, which a bare `.env` pattern does not cover. Outside a git
# work tree (or without git) there is nothing to commit, so the check passes.
#
# PROBE THE RESOLVED PATH — the writer does. `soleur_op_env_upsert` and
# `soleur_op_env_reset` both `readlink -f` before writing, so probing the link
# NAME asks git about a file the write never touches: a founder who symlinks
# .env at a shared credentials file gets an ignored name, a passing probe, and
# the value written to a target git reports as untracked-and-not-ignored. The
# `.tmp.XXXXXX` sibling is created beside the RESOLVED file too, so it is
# derived from the resolved path rather than from $ENV_FILE. Confirmed against
# a fixture; Guard 7's symlink rows pin it.
env_not_ignored() {
  local dir; dir="$(dirname "$1")"
  git -C "$dir" rev-parse --is-inside-work-tree >/dev/null 2>&1 || return 1
  ! git -C "$dir" check-ignore -q "$1"
}
ENV_FILE_RESOLVED="$(readlink -f -- "$ENV_FILE" 2>/dev/null || printf '%s' "$ENV_FILE")"
for probe in "$ENV_FILE_RESOLVED" "${ENV_FILE_RESOLVED}.tmp.XXXXXX"; do
  if env_not_ignored "$probe"; then
    printf 'SOLEUR_BOOTSTRAP_ENV_NOT_IGNORED path=%s\n' "$probe"
    printf 'The credentials file would be committed. Add it to .gitignore first (a pattern such as .env* covers both the file and its temp sibling).\n'
    exit 64
  fi
done
unset probe

if [[ -n "$RESET_KEY" ]]; then
  soleur_op_env_reset "$ENV_FILE" "$RESET_KEY"
  soleur_op_green "Forgot ${RESET_KEY}. Re-run to be asked for it again."
  exit 0
fi

# --- terminal outcome --------------------------------------------------------
# ONE trap. On a non-zero exit inside a stage it tells the founder which stage
# stopped, that nothing else was changed, and the one command that resumes —
# and it settles the stage in the ledger as `failed` with the exit code, so the
# ledger can say something other than "ok" (review P2-12). A library refusal
# (INPUT_REQUIRED, ABORTED) has already printed its own marker and sentence and
# written its `run_halt` line before this fires; the trap adds the stage context.
SCRIPT_PATH="${SCRIPT_DIR}/$(basename "${BASH_SOURCE[0]}")"
CURRENT_STAGE_INDEX=0
CURRENT_STAGE_NAME=""
STAGE_CHANGED=""
mark_changed() { STAGE_CHANGED="${STAGE_CHANGED:+${STAGE_CHANGED}; }$1"; }
on_exit() {
  local rc=$?
  [[ "$rc" -ne 0 && "$CURRENT_STAGE_INDEX" -gt 0 ]] || return 0
  # "Nothing else was changed" is FALSE on one path the library documents: a
  # secret whose write returned 0 and whose read-back did not confirm it may be
  # live (SOLEUR_BOOTSTRAP_SECRET_VERIFY_FAILED). Telling the founder nothing
  # changed is precisely what stops them revoking it, so the library raises a
  # flag and this sentence defers to it.
  if [[ -n "${SOLEUR_OP_WRITE_MAY_HAVE_LANDED:-}" ]]; then
    printf 'Stopped during stage %s (%s). A credential may already have been written — check it and revoke it if you did not mean to. Run: bash %s — already-done steps are skipped.\n' \
      "$CURRENT_STAGE_INDEX" "$CURRENT_STAGE_NAME" "$SCRIPT_PATH"
  elif [[ -n "$STAGE_CHANGED" ]]; then
    printf 'Stopped during stage %s (%s) AFTER it may have changed production: %s. Read the lines above before re-running. Run: bash %s — already-done steps are skipped.\n' \
      "$CURRENT_STAGE_INDEX" "$CURRENT_STAGE_NAME" "$STAGE_CHANGED" "$SCRIPT_PATH"
  else
    printf 'Stopped during stage %s (%s). Nothing else was changed. Run: bash %s — already-done steps are skipped.\n' \
      "$CURRENT_STAGE_INDEX" "$CURRENT_STAGE_NAME" "$SCRIPT_PATH"
  fi
  soleur_op_stage_end "$CURRENT_STAGE_INDEX" "$CURRENT_STAGE_NAME" failed "$rc"
}
trap on_exit EXIT

# run_stage <index> <name> <function>
#   Begin/settle around every stage, and the context the EXIT trap reports.
run_stage() {
  CURRENT_STAGE_INDEX="$1"; CURRENT_STAGE_NAME="$2"; STAGE_CHANGED=""
  soleur_op_stage_begin "$1" "$2"
  "$3"
  soleur_op_stage_end "$1" "$2" ok 0
  CURRENT_STAGE_INDEX=0; CURRENT_STAGE_NAME=""; STAGE_CHANGED=""
}

# =============================================================================
# STAGES - #9321 (ADR-241 D11): give the two App-token release jobs a Doppler
# credential that reads ONLY the two soleur-infra App values.
#
# CANONICAL SEQUENCE: knowledge-base/engineering/operations/runbooks/infra-credential-tiers-8209.md
# section "Release-job App source (#9321)". This script is the runnable form
# hr-multi-step-post-merge-bootstrap-script requires; it does not restate the runbook's reasoning.
#
# RUN IT AFTER the PR that adds Terraform's two empty containers has merged and its push apply
# succeeded (preflight fails with a named cause otherwise), and BEFORE the second PR (the switch of
# the composite action, the two release workflows and their suites) is merged.
#
# Shape of every stage: precondition ("already satisfied?", read from the vendor), the exact command,
# a per-command `yes` (class 2, no skip variable), then PASS/FAIL checks. No stage prints a secret
# value: values and the token move only through pipes, a child's environment or a stdin body. An
# UNREADABLE or INCONCLUSIVE read is never a PASS.
#
# Needs, on the operator's machine: doppler (logged in with access to soleur-infra-privileged and
# soleur-infra-app), gh (authenticated as a repo admin), jq, curl, openssl, sha256sum.
# =============================================================================

REPO="jikig-ai/soleur"
SRC_PROJECT="soleur-infra-privileged"
DST_PROJECT="soleur-infra-app"
CFG="prd"
GH_ENVIRONMENT="infra-privileged"
ENV_SECRET="DOPPLER_TOKEN_INFRA_APP"
READ_TOKEN_NAME="release-app-mint"
APP_SLUG="soleur-infra"
ID_NAME="GITHUB_INFRA_APP_ID"
PEM_NAME="GITHUB_INFRA_APP_PRIVATE_KEY"
# What a project-scoped read token's own download lists besides the secrets.
DOPPLER_META='["DOPPLER_CONFIG","DOPPLER_ENVIRONMENT","DOPPLER_PROJECT"]'
RUNBOOK="knowledge-base/engineering/operations/runbooks/infra-credential-tiers-8209.md"

# --- small helpers -------------------------------------------------------------

env_get() { # <KEY> -> the recorded non-secret value, or empty
  [[ -f "$ENV_FILE" ]] || return 0
  { grep -a "^$1=" "$ENV_FILE" || true; } | tail -1 | cut -d= -f2-
}

impact() { # <what users notice if it fails> <rollback>
  soleur_op_yellow "  If this fails: $1"
  soleur_op_yellow "  Rollback: $2"
}

show_cmd() { printf '  Command:\n    %s\n' "$*"; }

STAGE_FAILS=0
ORG_INCONCLUSIVE=0
check() { # <label> <0|1>
  if [[ "$2" == "0" ]]; then soleur_op_green "  PASS: $1"; else soleur_op_red "  FAIL: $1"; STAGE_FAILS=$((STAGE_FAILS + 1)); fi
}
stage_verdict() { # returns 1 when any check in the stage failed
  local n="$STAGE_FAILS"; STAGE_FAILS=0
  [[ "$n" -eq 0 ]] || { soleur_op_red "  ${n} check(s) failed - see the runbook section before re-running."; return 1; }
}

now_iso() { soleur_op_now; }

# val_hash <project> <name> -> sha256 of the value (trailing newlines stripped), or EMPTY when the
# read failed or the value is empty. Only the hash is ever printed.
val_hash() {
  local v
  v="$(doppler secrets get "$2" -p "$1" -c "$CFG" --plain 2>/dev/null)" || return 0
  [[ -n "$v" ]] || return 0
  printf '%s' "$v" | sha256sum | cut -d' ' -f1
}

# Name lists. A failed read prints nothing and returns non-zero: an unreadable list is
# INCONCLUSIVE, never "the name is absent".
env_secret_names() { gh api "repos/${REPO}/environments/${GH_ENVIRONMENT}/secrets" --paginate --jq '.secrets[].name' 2>/dev/null; }
repo_secret_names() { gh api "repos/${REPO}/actions/secrets" --paginate --jq '.secrets[].name' 2>/dev/null; }
org_secret_names() { gh api "orgs/${REPO%%/*}/actions/secrets" --paginate --jq '.secrets[].name' 2>/dev/null; }

token_slugs() { # slugs of the tokens named READ_TOKEN_NAME on the isolated project's prd config
  doppler configs tokens -p "$DST_PROJECT" -c "$CFG" --json 2>/dev/null \
    | jq -r --arg n "$READ_TOKEN_NAME" '.[] | select(.name == $n) | .slug' 2>/dev/null
}
token_names_all() { # every token name on the config, sorted, comma-joined; fails when unreadable
  doppler configs tokens -p "$DST_PROJECT" -c "$CFG" --json 2>/dev/null \
    | jq -er '[.[].name] | sort | join(",")' 2>/dev/null
}

b64url() { openssl base64 -A | tr '+/' '-_' | tr -d '='; }

# app_probe <app id> <pem> -> "<http code> <slug> <id>" from GET /app with an RS256 App JWT
# (iat=now-60, exp=now+300). The JWT goes to curl as a header on stdin, never argv.
app_probe() {
  local now hdr pl sig jwt body code
  now="$(date +%s)"
  hdr="$(printf '{"alg":"RS256","typ":"JWT"}' | b64url)"
  pl="$(printf '{"iat":%d,"exp":%d,"iss":"%s"}' $((now - 60)) $((now + 300)) "$1" | b64url)"
  sig="$(printf '%s.%s' "$hdr" "$pl" | openssl dgst -sha256 -binary -sign <(printf '%s\n' "$2") | b64url)" || sig=""
  [[ -n "$sig" ]] || { printf '000 - -'; return 0; }
  jwt="${hdr}.${pl}.${sig}"
  body="$(mktemp)"
  code="$(printf 'Authorization: Bearer %s\nAccept: application/vnd.github+json\n' "$jwt" \
    | curl --disable --noproxy '*' --proto '=https' -sS --max-time 15 -o "$body" -w '%{http_code}' -H @- \
      "https://api.github.com/app" 2>/dev/null)" || code="000"
  unset jwt
  printf '%s %s %s' "$code" "$(jq -r '.slug // "-"' "$body" 2>/dev/null || echo -)" "$(jq -r '.id // "-"' "$body" 2>/dev/null || echo -)"
  rm -f "$body"
}

# =============================================================================
# 1 - preflight (read-only)
# =============================================================================
# shellcheck disable=SC2319 # check() takes the condition's own status by design
stage_1_preflight() {
  impact "nothing changes here." "none needed."
  doppler projects get "$DST_PROJECT" --json >/dev/null 2>&1 \
    || { soleur_op_red "  Doppler project ${DST_PROJECT} is not readable. Either the merged PR's push apply (apply-web-platform-infra.yml) has not run or failed, or your Doppler login cannot see it. Fix that, then re-run."; return 1; }
  doppler secrets -p "$DST_PROJECT" -c "$CFG" --only-names >/dev/null 2>&1 \
    || { soleur_op_red "  ${DST_PROJECT}/${CFG} is not readable - the apply creates the prd environment with the project; check the run, then re-run."; return 1; }
  check "${SRC_PROJECT}/${CFG} holds a readable ${ID_NAME}" "$([[ -n "$(val_hash "$SRC_PROJECT" "$ID_NAME")" ]]; echo $?)"
  check "${SRC_PROJECT}/${CFG} holds a readable ${PEM_NAME}" "$([[ -n "$(val_hash "$SRC_PROJECT" "$PEM_NAME")" ]]; echo $?)"

  local policy custom names
  policy="$(gh api "repos/${REPO}/environments/${GH_ENVIRONMENT}/deployment-branch-policies" --jq '[.branch_policies[] | select((.type // "branch") == "branch") | .name] | sort | join(",")' 2>/dev/null)" || policy=""
  custom="$(gh api "repos/${REPO}/environments/${GH_ENVIRONMENT}" --jq '.deployment_branch_policy.custom_branch_policies' 2>/dev/null)" || custom=""
  check "environment ${GH_ENVIRONMENT} is restricted to custom branch policies" "$([[ "$custom" == "true" ]]; echo $?)"
  check "environment ${GH_ENVIRONMENT}'s only deployment branch is main (got '${policy:-unreadable}')" "$([[ "$policy" == "main" ]]; echo $?)"

  # A same-named secret at repository or organisation level is reachable from any branch's workflow.
  if names="$(repo_secret_names)"; then
    check "no repository-level secret named ${ENV_SECRET} (it would be branch-reachable)" "$(grep -qxF "$ENV_SECRET" <<<"$names"; echo $((1 - $? )))"
  else
    check "the repository-level secret list is readable (INCONCLUSIVE otherwise)" 1
  fi
  if names="$(org_secret_names)"; then
    check "no organisation-level secret named ${ENV_SECRET}" "$(grep -qxF "$ENV_SECRET" <<<"$names"; echo $((1 - $? )))"
  else
    ORG_INCONCLUSIVE=1
    soleur_op_yellow "  INCONCLUSIVE: the organisation-level secret list is not readable with this gh login (needs org admin). Check Settings -> Secrets on the organisation by hand before relying on the narrowing."
  fi
  stage_verdict
}

# =============================================================================
# 2 - copy the two App values into the isolated project
# =============================================================================
copy_one() { # <name>
  doppler secrets get "$1" -p "$SRC_PROJECT" -c "$CFG" --plain \
    | doppler secrets set "$1" -p "$DST_PROJECT" -c "$CFG" --silent >/dev/null
}
# shellcheck disable=SC2319 # check() takes the condition's own status by design
stage_2_copy() {
  local name src dst todo=""
  for name in "$ID_NAME" "$PEM_NAME"; do
    src="$(val_hash "$SRC_PROJECT" "$name")"
    dst="$(val_hash "$DST_PROJECT" "$name")"
    [[ -n "$src" ]] || { soleur_op_red "  ${name} is not readable from ${SRC_PROJECT}/${CFG}; nothing to copy."; return 1; }
    [[ -n "$dst" && "$src" == "$dst" ]] || todo="${todo:+${todo} }${name}"
  done
  if [[ -z "$todo" ]]; then
    soleur_op_yellow "  already satisfied: both values in ${DST_PROJECT}/${CFG} equal the ${SRC_PROJECT}/${CFG} copies"
    return 0
  fi
  impact "nothing user-facing: the copy is not read by any job until the switch PR merges." \
         "delete ${todo} from ${DST_PROJECT}/${CFG} (the source is untouched)."
  show_cmd "doppler secrets get <NAME> -p ${SRC_PROJECT} -c ${CFG} --plain | doppler secrets set <NAME> -p ${DST_PROJECT} -c ${CFG} --silent >/dev/null   (for: ${todo})"
  soleur_op_ack_or_die "  Copy ${todo} into ${DST_PROJECT}/${CFG}? Type 'yes': "
  mark_changed "${todo} may have been written to ${DST_PROJECT}/${CFG}"
  for name in $todo; do copy_one "$name"; done
  for name in "$ID_NAME" "$PEM_NAME"; do
    check "${name}: the copy equals its source (hash compared in-process)" \
      "$([[ -n "$(val_hash "$DST_PROJECT" "$name")" && "$(val_hash "$DST_PROJECT" "$name")" == "$(val_hash "$SRC_PROJECT" "$name")" ]]; echo $?)"
  done
  stage_verdict
}

# =============================================================================
# 3 - prove the copy is the live App (read-only)
# =============================================================================
# shellcheck disable=SC2319 # check() takes the condition's own status by design
stage_3_live() {
  local id pem probe
  id="$(doppler secrets get "$ID_NAME" -p "$DST_PROJECT" -c "$CFG" --plain 2>/dev/null)" || id=""
  pem="$(doppler secrets get "$PEM_NAME" -p "$DST_PROJECT" -c "$CFG" --plain 2>/dev/null)" || pem=""
  [[ -n "$id" && -n "$pem" ]] || { soleur_op_red "  the copies are not readable from ${DST_PROJECT}/${CFG}; re-run stage 2."; return 1; }
  probe="$(app_probe "$id" "$pem")"; unset pem
  case "$probe" in
    "200 ${APP_SLUG} ${id}") check "a JWT from the copy gets 200 from GET /app with slug=${APP_SLUG} id=${id}" 0 ;;
    401\ *) soleur_op_red "  GitHub answered 401: the copy is a stale or wrong key. Fix the source, then re-run stage 2 (it re-copies on a hash difference)."; check "a JWT from the copy is accepted by GitHub" 1 ;;
    *) check "GET /app with the copy gave a verdict (got '${probe%% *}'; a timeout or another App's answer is INCONCLUSIVE)" 1 ;;
  esac
  stage_verdict
}

# =============================================================================
# 4 - mint the read token, prove its reach, store it as an ENVIRONMENT secret
# =============================================================================
# tok_verify <token> -> the reach checks; the token travels only in a child's environment.
# shellcheck disable=SC2319 # check() takes the condition's own status by design
tok_verify() {
  local names out rc refused target
  names="$(DOPPLER_TOKEN="$1" doppler secrets download --no-file --no-fallback --format json --project "$DST_PROJECT" --config "$CFG" 2>/dev/null \
    | jq -er --argjson meta "$DOPPLER_META" 'keys - $meta | sort | join(",")' 2>/dev/null)" || names=""
  check "the token lists exactly ${ID_NAME},${PEM_NAME} in ${DST_PROJECT}/${CFG} (got '${names:-unreadable}')" \
    "$([[ "$names" == "${ID_NAME},${PEM_NAME}" ]]; echo $?)"
  # "refused" means a recognised access-denied answer. A transport error or an unknown shape is
  # INCONCLUSIVE, never a pass.
  for target in "${SRC_PROJECT}:${ID_NAME}" "soleur:GITHUB_APP_ID"; do
    refused=1
    rc=0
    out="$(DOPPLER_TOKEN="$1" doppler secrets get "${target#*:}" --plain --project "${target%%:*}" --config "$CFG" 2>&1)" || rc=$?
    if [[ "$rc" -ne 0 ]] && grep -qiE 'access|permission|forbidden|unauthori[sz]ed|not authori[sz]ed' <<<"$out"; then refused=0; fi
    unset out
    check "the token is REFUSED on ${target%%:*}/${CFG} (a recognised access-denied answer)" "$refused"
  done
}

# has_env_secret -> 0 present, 1 absent, 2 UNREADABLE. An unreadable list is INCONCLUSIVE, never "absent".
has_env_secret() {
  local names
  names="$(env_secret_names)" || return 2
  grep -qxF "$ENV_SECRET" <<<"$names" && return 0
  return 1
}

# revoke_confirmed <slug> -> 0 only when the slug is gone afterwards. A failed revoke is never reported as done.
revoke_confirmed() {
  local left
  doppler configs tokens revoke "$1" -p "$DST_PROJECT" -c "$CFG" >/dev/null 2>&1 || true
  left="$(token_slugs)" || { soleur_op_red "  could not re-list the tokens after revoking ${1}; check ${DST_PROJECT}/${CFG} before relying on it."; return 1; }
  if grep -qxF "$1" <<<"$left"; then
    soleur_op_red "  COULD NOT revoke token ${1}. Run: doppler configs tokens revoke ${1} -p ${DST_PROJECT} -c ${CFG}"
    return 1
  fi
}

# shellcheck disable=SC2319 # check() takes the condition's own status by design
stage_4_token() {
  local slugs count recorded stored prev_rec before new_slug tokval="" prev="" has_rc=0
  slugs="$(token_slugs)" || { soleur_op_red "  cannot list tokens on ${DST_PROJECT}/${CFG} - an unreadable list is not 'none'."; return 1; }
  count="$(grep -c . <<<"$slugs" || true)"
  recorded="$(env_get TOKEN_SLUG)"
  stored="$(env_get TOKEN_STORED)"
  prev_rec="$(env_get PREV_TOKEN_SLUG)"
  has_env_secret || has_rc=$?
  [[ "$has_rc" -ne 2 ]] || { soleur_op_red "  the ${GH_ENVIRONMENT} secret list is not readable with this gh login - INCONCLUSIVE, not 'absent'. Fix the login and re-run."; return 1; }

  # A rotation that crashed AFTER storing the new token leaves the previous one live: finish it.
  if [[ -n "$prev_rec" && "$count" == "2" && -n "$recorded" && "$stored" == "$recorded" ]] \
     && grep -qxF "$prev_rec" <<<"$slugs" && grep -qxF "$recorded" <<<"$slugs"; then
    soleur_op_yellow "  finishing an interrupted rotation: revoking the previous token ${prev_rec}"
    revoke_confirmed "$prev_rec" || return 1
    soleur_op_env_reset "$ENV_FILE" PREV_TOKEN_SLUG
    slugs="$recorded"; count=1
  fi

  # Already satisfied: exactly one token, it is the one this script recorded AND stored (TOKEN_STORED is written only after
  # the store and the listing check succeed), and the environment secret exists. Environment secrets are write-only, so the
  # name is all GitHub shows; the stored marker is what ties it to this token.
  if [[ "$ROTATE_TOKEN" != "1" && "$count" == "1" && "$has_rc" -eq 0 && -n "$recorded" && "$slugs" == "$recorded" && "$stored" == "$recorded" ]]; then
    soleur_op_yellow "  already satisfied: one token (${recorded}) was stored as ${GH_ENVIRONMENT} secret ${ENV_SECRET}"
    return 0
  fi
  if [[ -n "$(env_get TOKEN_MINT_ATTEMPTED)" ]]; then
    soleur_op_red "  A previous run started minting and was interrupted before it recorded the result."
    soleur_op_red "  Check the tokens on ${DST_PROJECT}/${CFG} (doppler configs tokens -p ${DST_PROJECT} -c ${CFG}) and revoke any named ${READ_TOKEN_NAME} that is not stored. Then run:"
    soleur_op_red "    bash ${SCRIPT_PATH} --reset TOKEN_MINT_ATTEMPTED"
    return 1
  fi
  if [[ "$count" -gt 1 ]]; then
    soleur_op_red "  ${DST_PROJECT}/${CFG} has ${count} tokens named ${READ_TOKEN_NAME}; this run cannot tell which one is stored."
    soleur_op_red "  Token values are not retrievable. Revoke all but the newest, then re-run:"
    # shellcheck disable=SC2001 # one slug per line; a prefix on each
    sed 's/^/    doppler configs tokens revoke /; s/$/ -p '"$DST_PROJECT"' -c '"$CFG"'/' <<<"$slugs"
    return 1
  fi
  if [[ "$count" == "1" ]]; then
    # One token exists and nothing proves it is the stored one (a lost .env, a crash between steps, or an explicit rotation).
    # Mint and store a new token FIRST, then revoke this one (new before old).
    prev="$slugs"
    soleur_op_yellow "  one token (${prev}) exists that this run cannot show is the stored one (or --rotate-token was given): a new token is minted and stored first, then ${prev} is revoked."
  fi

  impact "the release jobs are unaffected: nothing reads ${ENV_SECRET} until the switch PR merges." \
         "revoke ${READ_TOKEN_NAME} on ${DST_PROJECT}/${CFG} and delete ${ENV_SECRET} from the ${GH_ENVIRONMENT} environment."
  show_cmd "doppler configs tokens create ${READ_TOKEN_NAME} -p ${DST_PROJECT} -c ${CFG} --access read --plain  (kept in a shell variable only)"
  show_cmd "gh secret set ${ENV_SECRET} --env ${GH_ENVIRONMENT} -R ${REPO}  (token on stdin; ENVIRONMENT level, never repository level)"
  [[ -z "$prev" ]] || show_cmd "doppler configs tokens revoke ${prev} -p ${DST_PROJECT} -c ${CFG}  (only after the new token is stored)"
  soleur_op_ack_or_die "  Mint the read token, store it as the ${GH_ENVIRONMENT} environment secret${prev:+, then revoke ${prev}}? Type 'yes': "
  mark_changed "a read token may have been minted on ${DST_PROJECT}/${CFG} and stored as ${ENV_SECRET}"
  soleur_op_env_upsert "$ENV_FILE" TOKEN_MINT_ATTEMPTED "$(now_iso)"

  before="$slugs"
  tokval="$(doppler configs tokens create "$READ_TOKEN_NAME" -p "$DST_PROJECT" -c "$CFG" --access read --plain 2>/dev/null | tr -d '\n')" || tokval=""
  [[ -n "$tokval" ]] || { soleur_op_red "  minting failed (if the token was created server-side, the next run finds it by count)."; soleur_op_env_reset "$ENV_FILE" TOKEN_MINT_ATTEMPTED; return 1; }
  # The slug is recorded BEFORE the store, so a crash between mint and store leaves a revocable
  # record, not an orphan. The new slug is the one that was not there before.
  new_slug="$(comm -13 <(sort <<<"$before") <(token_slugs | sort) | head -1)"
  [[ -n "$new_slug" ]] || { unset tokval; soleur_op_red "  minted, but the new slug could not be identified; revoke tokens named ${READ_TOKEN_NAME} on ${DST_PROJECT}/${CFG} by hand."; return 1; }
  soleur_op_env_upsert "$ENV_FILE" TOKEN_SLUG "$new_slug"
  soleur_op_env_reset "$ENV_FILE" TOKEN_STORED
  [[ -z "$prev" ]] || soleur_op_env_upsert "$ENV_FILE" PREV_TOKEN_SLUG "$prev"
  soleur_op_env_reset "$ENV_FILE" TOKEN_MINT_ATTEMPTED

  tok_verify "$tokval"
  if ! stage_verdict; then
    unset tokval
    if revoke_confirmed "$new_slug"; then
      soleur_op_red "  the new token did not verify and was revoked (slug ${new_slug})."
      if [[ -n "$prev" ]]; then soleur_op_env_upsert "$ENV_FILE" TOKEN_SLUG "$prev"; else soleur_op_env_reset "$ENV_FILE" TOKEN_SLUG; fi
      soleur_op_env_reset "$ENV_FILE" PREV_TOKEN_SLUG
    fi
    return 1
  fi
  if ! printf '%s' "$tokval" | gh secret set "$ENV_SECRET" --env "$GH_ENVIRONMENT" -R "$REPO" >/dev/null; then
    unset tokval
    if revoke_confirmed "$new_slug"; then
      soleur_op_red "  storing ${ENV_SECRET} failed; the new token was revoked (slug ${new_slug})."
      if [[ -n "$prev" ]]; then soleur_op_env_upsert "$ENV_FILE" TOKEN_SLUG "$prev"; else soleur_op_env_reset "$ENV_FILE" TOKEN_SLUG; fi
      soleur_op_env_reset "$ENV_FILE" PREV_TOKEN_SLUG
    fi
    return 1
  fi
  unset tokval
  check "${ENV_SECRET} is listed on the ${GH_ENVIRONMENT} environment" "$(has_env_secret; echo $?)"
  stage_verdict || return 1
  soleur_op_env_upsert "$ENV_FILE" TOKEN_STORED "$new_slug"
  # Rotation: the old token is revoked only AFTER the new one is stored (new before old).
  if [[ -n "$prev" ]]; then
    revoke_confirmed "$prev" || return 1
    soleur_op_env_reset "$ENV_FILE" PREV_TOKEN_SLUG
    soleur_op_yellow "  revoked the previous token (${prev})"
  fi
}

# =============================================================================
# 5 - final read-only verification and the hand-off
# =============================================================================
# shellcheck disable=SC2319 # check() takes the condition's own status by design
stage_5_final() {
  local names all name
  check "the ${GH_ENVIRONMENT} environment lists ${ENV_SECRET}" "$(has_env_secret; echo $?)"
  if names="$(repo_secret_names)"; then
    check "the repository level does NOT list ${ENV_SECRET}" "$(grep -qxF "$ENV_SECRET" <<<"$names"; echo $((1 - $? )))"
  else
    check "the repository-level secret list is readable (INCONCLUSIVE otherwise)" 1
  fi
  all="$(token_names_all)" || all=""
  check "${DST_PROJECT}/${CFG} lists exactly one token, ${READ_TOKEN_NAME} (got '${all:-unreadable}')" "$([[ "$all" == "$READ_TOKEN_NAME" ]]; echo $?)"
  check "the recorded slug is the live token and was stored" "$([[ -n "$(env_get TOKEN_SLUG)" && "$(token_slugs)" == "$(env_get TOKEN_SLUG)" && "$(env_get TOKEN_STORED)" == "$(env_get TOKEN_SLUG)" ]]; echo $?)"
  for name in "$ID_NAME" "$PEM_NAME"; do
    check "${name}: the copy equals its source" \
      "$([[ -n "$(val_hash "$DST_PROJECT" "$name")" && "$(val_hash "$DST_PROJECT" "$name")" == "$(val_hash "$SRC_PROJECT" "$name")" ]]; echo $?)"
  done
  stage_verdict || return 1
  # "stored and scoped", not "works": the first proof is the first release run after the switch PR.
  printf 'SOLEUR_BOOTSTRAP_READY_FOR_PR2 repo=%s secret=%s environment=%s project=%s org_secret_list=%s\n' \
    "$REPO" "$ENV_SECRET" "$GH_ENVIRONMENT" "$DST_PROJECT" "$([[ "$ORG_INCONCLUSIVE" == "1" ]] && echo INCONCLUSIVE || echo clear)"
  echo "  Stored and scoped - not yet proven by a release run. The switch PR may be merged now; the proof is its first release run (runbook ${RUNBOOK})."
  [[ "$ORG_INCONCLUSIVE" != "1" ]] || soleur_op_yellow "  The organisation-level secret list was not readable: check the organisation's Actions secrets for ${ENV_SECRET} before relying on the narrowing."
}

main() {
  soleur_op_require_bins grep mktemp printenv sed date doppler gh jq curl openssl sha256sum comm sort cut tr head
  soleur_op_ledger_init "$TOTAL_STAGES" "bootstrap.sh"
  echo "Canonical sequence: ${RUNBOOK} - Release-job App source (#9321)."

  # No resume index: every stage's precondition makes a re-run from stage 1
  # skip what is already done, so re-run IS resume.
  run_stage 1 "preflight (read-only)" stage_1_preflight
  run_stage 2 "copy the two App values" stage_2_copy
  run_stage 3 "prove the copy is the live App" stage_3_live
  run_stage 4 "mint the read token and store it" stage_4_token
  run_stage 5 "final verification" stage_5_final

  soleur_op_summary_begin "BOOTSTRAP COMPLETE - the narrow credential is stored and scoped."
  soleur_op_summary_line "Next: merge the switch PR (composite action, two release workflows, two suites; Closes #9321), then run the proof dispatch in the runbook."
  soleur_op_summary_line "Recorded values (slugs, timestamps - no secrets): ${ENV_FILE} (mode 600)."
  soleur_op_summary_line "Run ledger: ${SOLEUR_BOOTSTRAP_LEDGER}"
}

main "$@"
